#include <iostream>
#include <algorithm>
#include <iomanip>

using namespace std;

using ll = long long;
using ld = long double;

const ll MAX = 100100;

ll N, c;
ld l, r, a, b;
ld A[MAX];
ld sol;

void DFS(ll n) {
    if (n > 1000000000LL) return;
    A[++N] = n;
    DFS(n * 10 + 4);
    DFS(n * 10 + 7);
}

ld prob(ld lol, ld hil, ld loa, ld hia) {
    lol = max(lol, l);
    hil = min(hil, r);
    loa = max(loa, a);
    hia = min(hia, b);

    ld cl = hil - lol + 1;
    ld ca = hia - loa + 1;
    if (min(cl, ca) <= 0) return 0;

    return (cl / (r - l + 1)) * (ca / (b - a + 1));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << setprecision(15) << fixed;

    DFS(4);
    DFS(7);
    sort(A, A + N);

    A[0] = 0;
    A[N + 1] = 1100100100;

    cin >> l >> r >> a >> b >> c;

    for (ll i = c; i <= N; ++i) {
        if (A[i] > max(b, r)) break;

        sol += prob(A[i - c] + 1, A[i - c + 1],
                    A[i], A[i + 1] - 1);
        sol += prob(A[i], A[i + 1] - 1,
                    A[i - c] + 1, A[i - c + 1]);
    }

    cout << sol << '\n';
    return 0;
}

